<?php
namespace Modules\Glitter\NotificationHub\Tests\Unit\DTO\Admin;use Modules\Glitter\NotificationHub\DTO\Admin\ManualRetryData;use Modules\Glitter\NotificationHub\Enums\RetryPolicy;use PHPUnit\Framework\TestCase;class ManualRetryDataTest extends TestCase{public function test_validated_values_are_typed():void{$d=ManualRetryData::fromArray(['request_id'=>'00000000-0000-4000-8000-000000000001','reason'=>'retry','retry_policy'=>'standard','max_attempts'=>6],1);$this->assertSame(RetryPolicy::Standard,$d->retryPolicy);$this->assertSame(1,$d->actorId);}public function test_request_id_may_be_omitted_or_empty():void{$this->assertNull(ManualRetryData::fromArray(['reason'=>'retry'],null)->requestId);$this->assertNull(ManualRetryData::fromArray(['request_id'=>'','reason'=>'retry'],null)->requestId);}}
